
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_th_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_th", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.942580051980059e+01, -1.830045821918797e+01, -1.679736467761697e+01, -1.485280082304901e+01, -1.244886825988538e+01, -9.662944723234554e+00, -6.717627308145540e+00, -3.986214438172844e+00, -1.888892983003546e+00, -6.696771357332377e-01, -2.230132843623080e-01, -2.911001443559145e-01, -7.678237142348372e-01, -6.300545693199511e-01, -2.303840635931415e-01, -4.961069618040024e-02, -5.379757711058947e-03, -2.240991273873205e-04, -2.355022365587093e-06, -3.492742988951309e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


